SELECT e.zone_id AS zone, any(z.name) AS zone_name, uniqExact(e.npc_name) AS npcs, uniqExact(e.event_id) AS events, sum(e.n) AS starts, uniqExact(e.capture_id) AS captures FROM (SELECT * FROM npc_events WHERE zone_id IS NOT NULL AND capture_id NOT IN (SELECT capture_id FROM capture_trust FINAL WHERE trust = 'flagged')) e LEFT JOIN (SELECT id, any(name) AS name FROM zone_names GROUP BY id) z ON z.id = e.zone_id GROUP BY e.zone_id ORDER BY zone_name, zone
